import './style.css';
import {ABILITIES,SKILLS,uid,blank,entry,validate,stats,sign,changeHp,rest,resolveExpression,rollDice,clamp} from './model.js';
import {DEFAULT_SOURCE,plain,parseCompendium,mergeCompendium,loadCompendium,classRows,syncClasses,advance,addCompendiumEntry} from './compendium.js';
import {vox} from './preset.js';
import {connect,inspectToken,saveToken,loadToken,shareRoll,receiveRoll} from './obr.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const moduleMode=location.pathname.includes('/builder/')?'builder':location.pathname.includes('/dice/')?'dice':new URLSearchParams(location.search).get('module')||'sheet';let rosterVisible=moduleMode==='sheet',settingsVisible=false;
let context=null,scope='dnd-chars-sheet:standalone:v1',store,tab=moduleMode==='builder'?'Builder':moduleMode==='dice'?'Dice':'Overview',mode='normal',critical=false,shared=false,search='',lastRoll=null,storageError=false;
const tabs=moduleMode==='builder'?['Builder']:moduleMode==='dice'?['Dice']:['Overview','Forms','Features','Spells','Inventory','Contacts & Notes'];
const CONDITIONS=['Blinded','Charmed','Deafened','Frightened','Grappled','Incapacitated','Invisible','Paralyzed','Petrified','Poisoned','Prone','Restrained','Stunned','Unconscious','Exhaustion'];
const freeDice=blank();freeDice.name='Free Dice';const current=()=>store.characters.find(c=>c.id===store.active)||store.characters[0]||(moduleMode==='dice'?freeDice:undefined);
function notify(s){$('#notice').textContent=s;$('#notice').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').hidden=true,4500);}
function persist(){try{localStorage.setItem('crucible:active-character-scope',scope);localStorage.setItem(scope,JSON.stringify(store));storageError=false;}catch{storageError=true;notify('Browser storage is unavailable or full. Export a JSON backup before closing.');}}
function init(){try{localStorage.setItem('crucible:active-character-scope',scope)}catch{};try{const raw=JSON.parse(localStorage.getItem(scope));if(Array.isArray(raw?.characters)){store={characters:raw.characters.slice(0,50).map(validate),active:raw.active,history:Array.isArray(raw.history)?raw.history.filter(r=>r&&typeof r.label==='string'&&typeof r.detail==='string'&&typeof r.character==='string'&&Number.isFinite(r.total)).slice(0,60):[]};}}catch{}if(!store)store={characters:[],history:[]};
if(!store.characters.length){try{const migrationKey='crucible:migrated:'+scope;const previous=JSON.parse(localStorage.getItem('shattered-crucible:v1:characters')||localStorage.getItem('sc-suite/characters')||'[]');if(!localStorage.getItem(migrationKey)&&Array.isArray(previous)&&previous.length){for(const old of previous.slice(0,50)){const converted=blank();converted.name=old.name||'Imported Sheet';converted.id=old.id||uid();converted.entityType=old.entityType||'PC';converted.portrait=old.portrait||'';converted.tokenFrame=old.tokenFrame||'gold';converted.species=old.species||'';converted.className=old.className||'';converted.subclass=old.subclass||'';converted.background=old.background||'';converted.level=Number(old.level)||1;converted.hp=Number(old.hp)||10;converted.maxHp=Number(old.maxHp)||Number(old.hp)||10;converted.acBase=Number(old.ac)||10;converted.speed=Number(old.speed)||30;converted.notes=old.notes||'';converted.contacts=old.contacts||'';for(const a of ABILITIES)converted.abilities[a]=Number(old[a]??old.abilities?.[a])||10;for(const k of ['spells','items','features','forms','attacks'])converted[k]=Array.isArray(old[k])?old[k]:[];store.characters.push(validate(converted))}store.active=store.characters[0]?.id;localStorage.setItem(scope,JSON.stringify(store));localStorage.setItem(migrationKey,'done')}}catch(error){console.warn('Legacy roster migration failed',error)}}if(!store.characters.some(c=>c.id===store.active))store.active=store.characters[0]?.id;render();}
const button=(label,action,extra='',cls='b')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const field=(label,path,value,type='text',extra='')=>`<label>${esc(label)}<input type="${type}" data-path="${esc(path)}" ${type==='checkbox'?(value?'checked':''):`value="${esc(value)}"`} ${extra}></label>`;
const area=(label,path,value)=>`<label class="fullwidth">${esc(label)}<textarea data-path="${esc(path)}">${esc(value)}</textarea></label>`;
const select=(label,path,value,options)=>`<label>${esc(label)}<select data-path="${esc(path)}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const check=(label,path,value)=>`<label class="inline-check"><input type="checkbox" data-path="${esc(path)}" ${value?'checked':''}>${esc(label)}</label>`;
const empty=text=>`<p class="list-empty">${text}</p>`;
function rollButton(label,expression,extra=''){return button(esc(label),'roll',`data-expression="${esc(expression)}" ${extra}`,'roll');}
function settingsPage(){return '<div class="c"><h2>SETTINGS · IMPORT / EXPORT</h2><p>Contract v1 is the default transport for character sheets and NPC/monster records.</p><div class="rest">'+button('EXPORT CONTRACT V1','contract-export','','b primary')+button('IMPORT CONTRACT V1','contract-import')+button('CLOSE SETTINGS','close-settings')+'</div><h3>Legacy dnd-chars-sheet migration</h3><p class="dm">Existing schema 1 JSON exports remain supported for backwards compatibility.</p><div class="rest">'+button('EXPORT CURRENT NATIVE SHEET','export')+button('IMPORT NATIVE SHEET','import')+'</div><p class="sm">Shared data is scoped to this Owlbear player and room. Imported characters appear in the roster.</p></div>';}
function portrait(c){const u=typeof c.portrait==='string'&&/^(https:\/\/|data:image\/(?:png|jpeg|webp);base64,)/i.test(c.portrait)?esc(c.portrait):'';return '<div class="portrait-frame frame-'+esc(c.tokenFrame||'gold')+'">'+(u?'<img src="'+u+'" alt="'+esc(c.name)+' portrait">':'<span aria-hidden="true">◈</span>')+'</div>';}
function rosterPage(){const total=store.characters.length;return '<section class="roster-head"><div><p class="eyebrow">YOUR CAMPAIGN ROSTER</p><h1>CHARACTER LIBRARY</h1><p class="dm">Players, NPCs, pets, familiars and monsters · '+total+' sheets</p></div><div class="roll-row">'+button('+ NEW SHEET','new','','b primary')+'</div></section>'+(total?'<div class="roster-grid">'+store.characters.map(c=>'<article class="roster-card">'+portrait(c)+'<div><b>'+esc(c.name)+'</b><small>'+esc(c.entityType||'PC')+' · '+esc(c.className||c.creatureType||'Adventurer')+'</small><small>LV '+c.level+' · HP '+c.hp+'/'+c.maxHp+' · '+(c.cr?'CR '+esc(c.cr):esc(c.species||''))+'</small></div>'+button('OPEN SHEET','open-sheet','data-value="'+esc(c.id)+'"','b primary')+'</article>').join('')+'</div>':'<div class="c"><h2>NO SHEETS YET</h2><p>Create a PC, NPC, familiar, pet or monster with the character builder.</p>'+button('CREATE YOUR FIRST SHEET','new','','b primary')+'</div>');}
function render(){if(settingsVisible){$('#app').innerHTML=appNavigation()+settingsPage();return;}if(moduleMode==='sheet'&&location.hash!=='#compendium'&&(rosterVisible||location.hash==='#roster')){$('#app').innerHTML=appNavigation()+rosterPage();return;}if(location.hash==='#compendium'){$('#app').innerHTML=appNavigation()+compendiumPage();return;}if(!current()){$('#app').innerHTML=appNavigation()+emptySheet();return;}const c=current(),s=stats(c);$('#app').innerHTML=appNavigation()+`<div class="toolbar sheet-tools no-print"><span class="brand">◈ dnd-chars-sheet</span><select id="character" aria-label="Active character">${store.characters.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${button('ALL SHEETS','roster')+button('+ NEW','new')}${button('⚙ SETTINGS','settings')}${button('IMPORT','import')}<div class="status ${storageError?'error':''}">${context?'● Owlbear connected · '+esc(context.name)+' · local saves for this player and room':'○ Standalone preview · saves in this browser'}${storageError?' · SAVE FAILED — export a backup':''}</div></div>
<header class="sheet-identity">${portrait(c)}<h1>${esc(c.name)}</h1><div class="sub">LEVEL ${c.level} · ${esc(c.species||'Species not set')} · ${esc(c.className||'Class not set')}${c.subclass?' / '+esc(c.subclass):''} · ${esc(c.rules)} RULES</div><div class="chips"><span class="chip">Player <b>${esc(c.player||context?.name||'—')}</b></span><span class="chip">Background <b>${esc(c.background||'—')}</b></span><span class="chip">Alignment <b>${esc(c.alignment||'—')}</b></span>${c.activeForm!==null?`<span class="chip am">FORM: ${esc(c.forms[c.activeForm]?.name)}</span>`:''}</div></header>
<div class="bar"><div class="st"><div class="v">${s.ac}</div><div class="l">ARMOR CLASS</div></div><div class="st hp"><div class="v">${c.hp}<span class="dm"> / ${c.maxHp}</span>${c.tempHp?` <small>+${c.tempHp}</small>`:''}</div><div class="l">HIT POINTS · ${c.tempHp} TEMP</div><div class="hp-actions no-print"><input id="hpAmount" type="number" min="0" max="9999" value="1" aria-label="Hit point amount">${button('−','damage','aria-label="Take damage"')}${button('+','heal','aria-label="Heal"')}${button('TEMP','temp')}</div></div><div class="st"><div class="v">${s.speed}</div><div class="l">SPEED · FT</div></div><div class="st"><div class="v">${sign(s.pb)}</div><div class="l">PROFICIENCY</div></div><div class="st"><div class="v">${s.spellDc}</div><div class="l">SPELL SAVE DC</div></div><div class="st"><div class="v">${rollButton(sign(s.spellAttack),'1d20'+sign(s.spellAttack),'data-label="Spell attack"')}</div><div class="l">SPELL ATTACK</div></div><div class="st"><div class="v">${10+s.skills.Perception}</div><div class="l">PASSIVE PERCEPTION</div></div></div>
<div class="abil">${ABILITIES.map(a=>`<div class="ab ${c.saves.includes(a)?'p':''}"><div class="n">${a.toUpperCase()}</div><div class="m">${rollButton(sign(s.mods[a]),'1d20'+sign(s.mods[a]),`data-label="${a.toUpperCase()} check"`)}</div><div class="s">${s.abilities[a]} · save ${rollButton(sign(s.saves[a]),'1d20'+sign(s.saves[a]),`data-label="${a.toUpperCase()} save"`)}</div></div>`).join('')}</div>
<div class="toolbar no-print"><div class="dice-mode">${['disadvantage','normal','advantage'].map(m=>button(m==='disadvantage'?'DIS':m==='advantage'?'ADV':'NORMAL','mode',`data-value="${m}"`,m===mode?'b active':'b')).join('')}${button('CRIT','crit',`aria-pressed="${critical}"`,critical?'b active':'b')}</div><label class="inline-check"><input id="shared" type="checkbox" ${shared?'checked':''} ${context?'':'disabled'}>Share rolls with room</label></div>
<nav class="no-print">${tabs.map(t=>button(t,'tab',`data-value="${t}"`,t===tab?'on':'')).join('')}</nav><main class="tab-panel">${panel(c,s)}</main>
<footer class="no-print"><span class="sm">Local autosave · token snapshots are manual · v1.2.0</span><div>${button('SAVE TO TOKEN','save-token',context?'':'disabled')}${button('LOAD TOKEN','load-token',context?'':'disabled')}${button('PRINT','print')}</div></footer>`;const active=$('nav .on');if(active)$('nav').scrollLeft=Math.max(0,active.offsetLeft-$('nav').offsetLeft-$('nav').clientWidth+active.offsetWidth);}
function panel(c,s){switch(tab){case'Overview':return overview(c,s);case'Forms':return forms(c,s);case'Features':return features(c);case'Spells':return spells(c,s);case'Inventory':return inventory(c);case'Contacts & Notes':return notes(c);case'Dice':return dice(c,s);case'Builder':return builder(c);case'Compendium':return compendiumPanel();}}
function resources(c){return c.resources.map((r,i)=>`<div class="tr"><div><b>${esc(r.name)}</b><small>${esc(r.description)} · ${r.reset==='none'?'Manual reset':r.reset+' rest reset'}${r.shortAmount?' · short rest +'+r.shortAmount:''}</small></div><div>${button('−','resource',`data-index="${i}" data-value="1" aria-label="Spend ${esc(r.name)}"`)} <b>${r.max-r.used} / ${r.max}</b> ${button('+','resource',`data-index="${i}" data-value="-1" aria-label="Restore ${esc(r.name)}"`)}</div></div>`).join('')||empty('Add resource trackers in Builder.');}
function overview(c,s){return `<div class="rest">${rollButton('Initiative','1d20'+sign(s.initiative),'data-label="Initiative"')}${rollButton('Concentration','1d20'+sign(s.saves.con),'data-label="Concentration"')}${button('SHORT REST','rest','data-value="short"')}${button('LONG REST','rest','data-value="long"')}</div><div class="g"><div class="c full"><h2>Attacks</h2>${c.activeForm!==null?'<p class="note">A form is active. Use its attacks in Forms; normal attacks remain below for reference.</p>':''}${c.attacks.length?`<table><thead><tr><th>ATTACK</th><th>HIT</th><th>DAMAGE</th></tr></thead><tbody>${c.attacks.map((a,i)=>`<tr><td><details><summary class="cy">${esc(a.name)}</summary><p class="sm">${esc(a.description)}</p></details><small class="dm">${esc(a.range)} · ${esc(a.damageType)}</small></td><td>${rollButton(sign((a.spellAttack?s.spellAttack:s.mods[a.ability]+(a.proficient?s.pb:0))+a.bonus),'1d20'+sign((a.spellAttack?s.spellAttack:s.mods[a.ability]+(a.proficient?s.pb:0))+a.bonus),`data-label="${esc(a.name)} attack"`)}</td><td>${rollButton(resolveExpression(a.damage,c,a.ability),resolveExpression(a.damage,c,a.ability),`data-label="${esc(a.name)} ${a.heal?'healing':'damage'}" data-damage="${!a.heal}"`)}</td></tr>`).join('')}</tbody></table>`:empty('Add attacks in Builder.')}</div><div class="c"><h2>Skills</h2><div class="sk">${Object.keys(SKILLS).map(k=>`<div><span>${c.skills[k]===2?'◆◆':c.skills[k]===1?'◆':c.skills[k]===0.5?'◐':'◇'} ${k}</span>${rollButton(sign(s.skills[k]),'1d20'+sign(s.skills[k]),`data-label="${k}"`)}</div>`).join('')}</div></div><div class="c"><h2>Resources</h2>${resources(c)}${c.classes?.length?classPanel(c):`<div class="tr"><span>Hit Dice: ${c.level-c.hitDiceSpent} / ${c.level} d${c.hitDie}</span>${button('SPEND & HEAL','hit-die')}</div>`}${check('Heroic Inspiration','inspiration',c.inspiration)}<h3>Death saves</h3><div class="roll-row">${button('ROLL DEATH SAVE','death')}<span>${c.deathSuccess} successes · ${c.deathFail} failures</span>${button('RESET','death-reset')}</div><p class="sm">Death saves ignore ADV/DIS. A natural 20 restores 1 HP. Conditions and exhaustion are tracked manually.</p></div><div class="c full"><h2>Conditions & Concentration</h2><div class="roll-row">${CONDITIONS.map(k=>button(k,'condition',`data-value="${k}"`,c.conditions.includes(k)?'b pill on':'b pill')).join('')}</div><div class="builder-grid">${field('Concentrating on','concentration',c.concentration)}</div><p class="sm">Use ADV for War Caster concentration checks; DIS and ADV cancel by selecting NORMAL. Gear effects remain active while transformed until unequipped.</p></div></div>`;}
function forms(c){return `${c.activeForm!==null?`<div class="active-form">◈ ${esc(c.forms[c.activeForm].name)} active · ${button('REVERT','revert')}</div>`:''}<p class="note">Forms replace STR, DEX, CON, AC and speed, grant the configured temporary HP, and spend one named resource. Mental abilities and character proficiencies remain. Review beast skill bonuses, equipment, duration and restrictions manually.</p><div class="g">${c.forms.map((f,i)=>`<div class="c"><h2>${esc(f.name)}</h2><p>AC ${f.ac} · Speed ${f.speed} ft. · STR ${f.str} / DEX ${f.dex} / CON ${f.con}</p><p class="dm">${esc(f.description)}</p><div class="roll-row">${f.attacks.map((a,j)=>`${rollButton(a.name+' '+sign(a.bonus),'1d20'+sign(a.bonus),`data-label="${esc(f.name+' '+a.name)} attack"`)}${rollButton(a.damage,a.damage,`data-label="${esc(f.name+' '+a.name)} damage" data-damage="true"`)}`).join('')}</div>${button('ASSUME FORM','form',`data-index="${i}"`)}<p class="sm">${f.tempHp} temporary HP · ${esc(f.resource)||'no tracked resource'}</p></div>`).join('')||empty('Add a form in Builder.')}</div>`;}
function features(c){return `<div class="c"><h2>Proficiencies & Languages</h2><p style="white-space:pre-wrap">${esc(c.proficiencies)||'Add armor, weapon, tool and language proficiencies in Builder.'}</p></div><br>${c.features.map(f=>`<details class="entry"><summary>${esc(f.name)}</summary><p>${esc(f.description)}</p>${f.roll?rollButton(f.roll,resolveExpression(f.roll,c),'data-label="'+esc(f.name)+'"'):''}</details>`).join('')||empty('Add features and feats in Builder.')}`;}
function spells(c,s){return `<div class="c"><h2>Spell slots</h2><p class="sm">Filled slots are spent. Click a slot to toggle it. Cast spends the selected level; upcast damage must be entered manually.</p><div class="slots">${c.slots.map((n,i)=>n?`<div class="slot">Level ${i+1}<div>${Array.from({length:n},(_,j)=>button(j<c.spentSlots[i]?'●':'○','slot',`data-index="${i}" data-value="${j}" aria-label="Level ${i+1} slot ${j+1}: ${j<c.spentSlots[i]?'spent':'available'}"`)).join('')}</div>${n-c.spentSlots[i]} / ${n}</div>`:'').join('')||'<p class="dm">Set slots in Builder.</p>'}</div></div><br><input class="search" id="search" placeholder="Search spells…" value="${esc(search)}" aria-label="Search spells"><div id="spell-list">${spellList(c,s)}</div>`;}
function spellList(c,s){return [...c.spells].map((x,i)=>({...x,index:i})).sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name)).filter(x=>(x.name+' '+x.description).toLowerCase().includes(search.toLowerCase())).map(sp=>`<details class="entry"><summary>${esc(sp.name)} <span class="tag">${sp.level?'LEVEL '+sp.level:'CANTRIP'}</span>${sp.always?' <span class="sm">always prepared</span>':sp.prepared?' <span class="sm">prepared</span>':''}</summary><div class="meta">${esc(sp.castingTime)} · ${esc(sp.range)} · ${esc(sp.duration)} · ${esc(sp.components)}${sp.concentration?' · CONCENTRATION':''}${sp.ritual?' · RITUAL':''}</div><p>${esc(sp.description)||'Add spell text in Builder.'}</p>${sp.save?`<p>${esc(sp.save.toUpperCase())} save · DC ${s.spellDc}</p>`:''}<div class="roll-row">${sp.level?`<select id="cast-level-${sp.index}" aria-label="Cast ${esc(sp.name)} at level">${Array.from({length:10-sp.level},(_,i)=>`<option value="${sp.level+i}">Level ${sp.level+i}</option>`).join('')}</select>`:''}${button('CAST','cast',`data-index="${sp.index}"`)}${sp.ritual?button('RITUAL','ritual',`data-index="${sp.index}"`):''}${sp.rollKind==='attack'?rollButton('ATTACK '+sign(s.spellAttack),'1d20'+sign(s.spellAttack),`data-label="${esc(sp.name)} attack"`):''}${sp.roll?rollButton(resolveExpression(sp.roll,c),resolveExpression(sp.roll,c),`data-label="${esc(sp.name)} ${sp.rollKind==='heal'?'healing':'effect'}" data-damage="${['attack','damage'].includes(sp.rollKind)}"`):''}</div><p class="sm">Casting tracks a slot and concentration only. Roll the effect separately; apply damage/healing to the intended target manually.</p></details>`).join('')||empty('No spells match. Add spells in Builder.');}
function inventory(c){return `<div class="c"><h2>Equipment</h2><p class="sm">Equipped items apply configured bonuses. Items requiring attunement need both toggles. Attuned: ${c.items.filter(i=>i.attuned).length} / 3 (manual limit).</p><div class="currency">${['gold','silver','copper'].map(k=>field(k.toUpperCase(),k,c[k],'number','min="0"')).join('')}</div></div><br>${c.items.map((it,i)=>`<details class="entry"><summary>${esc(it.name)} <span class="tag">× ${it.quantity}</span></summary><p>${esc(it.description)||'No description yet.'}</p><div class="roll-row">${check('Equipped',`items.${i}.equipped`,it.equipped)}${check('Attuned',`items.${i}.attuned`,it.attuned)}${field('Quantity',`items.${i}.quantity`,it.quantity,'number','min="0"')}${it.roll?rollButton(it.roll,resolveExpression(it.roll,c),`data-label="${esc(it.name)}"`):''}</div><p class="sm">${it.weight} lb each · Bonuses: AC ${sign(it.ac)} / saves ${sign(it.saves)} / spell attack ${sign(it.spellAttack)} / spell DC ${sign(it.spellDc)}</p></details>`).join('')||empty('Add inventory items in Builder.')}<div class="builder-grid">${area('Inventory notes','inventoryNotes',c.inventoryNotes)}</div>`;}
function notes(c){return `<div class="builder-grid">${area('Connections / important NPCs','contacts',c.contacts)}${area('Backstory — player-owned','backstory',c.backstory)}${area('Personality / ideals / bonds / flaws','personality',c.personality)}${area('Field notes','notes',c.notes)}</div><p class="sm">Notes stay in this browser unless exported or explicitly saved to a shared token.</p>`;}
function history(){return store.history.map(r=>`<div class="roll-entry"><div><b>${esc(r.label)}</b><small>${esc(r.character)}${r.remote?' · ROOM':''} · ${esc(r.expression)}${r.mode&&r.mode!=='normal'?' · '+esc(r.mode):''}${r.crit?' · CRITICAL':''}</small><small>${esc(r.detail)}</small></div><strong>${r.total}</strong></div>`).join('')||empty('Roll a stat, attack, spell, or die.');}
function dice(c,s){return `<div class="g"><div class="c"><h2>Dice roller</h2><div class="result">${lastRoll?lastRoll.total:'—'}</div><p class="sm" style="text-align:center">${lastRoll?esc(lastRoll.label+' · '+lastRoll.detail):'Click a die or enter a formula'}</p><div class="roll-row">${[4,6,8,10,12,20,100].map(n=>rollButton('d'+n,'1d'+n,`data-label="d${n}"`)).join('')}</div><div class="roll-row"><input id="formula" value="1d20+5" aria-label="Dice formula" style="flex:1">${button('ROLL','formula')}</div><label class="inline-check"><input type="checkbox" id="formulaDamage">Treat formula as damage (allows CRIT)</label><p class="sm">Examples: 2d6+3, 1d20+5, 2d8+1d4-1. No automatic critical hits or success checks. CRIT doubles damage dice only.</p><div class="roll-row">${rollButton('Initiative','1d20'+sign(s.initiative),'data-label="Initiative"')}${rollButton('Spell attack','1d20'+sign(s.spellAttack),'data-label="Spell attack"')}${rollButton('Concentration','1d20'+sign(s.saves.con),'data-label="Concentration"')}</div></div><div class="c"><h2>Roll history</h2>${button('CLEAR HISTORY','clear-history')}<div id="history">${history()}</div></div></div>`;}
function builder(c){return `${classPanel(c)}<p class="builder-note">Use the character wizard to create a character, then edit its details here. Derived modifiers, proficiency, saves, skills and spell values update from these fields. Choose your own class features, spells, slots and equipment; this builder does not enforce class or edition rules.</p><div class="toolbar">${button('DUPLICATE','duplicate')}${button('ADD VOX PRESET','preset')}${button('DELETE CHARACTER','delete-character','','b danger')}</div><div class="c"><h2>Identity</h2><div class="builder-grid">${field('Name','name',c.name)+select('Sheet type','entityType',c.entityType,['PC','NPC','Familiar','Monster'])+field('Portrait URL','portrait',c.portrait)+`<label>Upload portrait image (PNG, JPEG or WebP, max 4 MB)<input type="file" id="portrait-upload" accept="image/png,image/jpeg,image/webp"></label>`+select('Token frame','tokenFrame',c.tokenFrame,['gold','silver','arcane','nature','infernal','none'])+field('Owner / handler','owner',c.owner)+field('Challenge rating','cr',c.cr)+field('Creature type','creatureType',c.creatureType)+select('Size','size',c.size,['Tiny','Small','Medium','Large','Huge','Gargantuan'])}${field('Player','player',c.player)}${field('Species / ancestry','species',c.species)}${field('Class summary','className',c.className,'text',c.classes?.length?'readonly':'')}${field('Subclass','subclass',c.subclass,'text',c.classes?.length?'readonly':'')}${field('Total level','level',c.level,'number','min="1" max="20" '+(c.classes?.length?'readonly':''))}${field('Background','background',c.background)}${field('Alignment','alignment',c.alignment)}${select('Rules','rules',c.rules,['2024','2014','Custom'])}${area('Armor / weapons / tools / languages','proficiencies',c.proficiencies)}</div></div><br><div class="c"><h2>Abilities & Saving Throws</h2><div class="builder-grid">${ABILITIES.map(a=>field(a.toUpperCase(),`abilities.${a}`,c.abilities[a],'number','min="1" max="30"')).join('')}</div><div class="check-grid" style="margin-top:12px">${ABILITIES.map(a=>`<label class="inline-check"><input type="checkbox" data-save-prof="${a}" ${c.saves.includes(a)?'checked':''}>${a.toUpperCase()} save proficiency</label>`).join('')}</div></div><br><div class="c"><h2>Combat & Spellcasting</h2><div class="builder-grid">${field('Maximum HP','maxHp',c.maxHp,'number','min="1" max="9999"')}${field('Current HP','hp',c.hp,'number','min="0"')}${field('Temporary HP','tempHp',c.tempHp,'number','min="0"')}${select('Hit Die','hitDie',c.hitDie,[4,6,8,10,12,20].map(n=>[n,'d'+n]))}${field('Hit Dice spent','hitDiceSpent',c.hitDiceSpent,'number','min="0" '+(c.classes?.length?'readonly':''))}${field('Base armor AC','acBase',c.acBase,'number')}${field('Add DEX to AC','acDex',c.acDex,'checkbox')}${field('DEX contribution cap','acDexCap',c.acDexCap,'number','min="0" max="10"')}${field('Shield AC','shield',c.shield,'number')}${field('Other AC bonus','acBonus',c.acBonus,'number')}${field('Speed (ft.)','speed',c.speed,'number','min="0"')}${field('Initiative bonus','initiativeBonus',c.initiativeBonus,'number')}${field('All saves bonus','saveBonus',c.saveBonus,'number')}${select('Spellcasting ability','spellAbility',c.spellAbility,ABILITIES.map(a=>[a,a.toUpperCase()]))}${field('Spell attack bonus','spellAttackBonus',c.spellAttackBonus,'number')}${field('Spell DC bonus','spellDcBonus',c.spellDcBonus,'number')}</div><p class="sm">AC = base + capped DEX (if enabled) + shield + other bonus + active item bonuses. Use base 10 for unarmored, base 11 for leather; turn DEX off for fixed armor. Custom formulas can be entered through base and bonus fields.</p></div><br><details class="c"><summary class="am">SKILLS — proficiency, expertise, custom bonuses</summary><div class="builder-grid">${Object.keys(SKILLS).map(k=>`<div>${select(k,`skills.${k}`,c.skills[k]||0,[[0,'Not proficient'],[0.5,'Half proficiency'],[1,'Proficient'],[2,'Expertise']])}${field('Extra bonus',`skillBonuses.${k}`,c.skillBonuses[k]||0,'number')}</div>`).join('')}</div></details><br><div class="c"><h2>Spell slot capacity</h2><div class="builder-grid">${c.slots.map((n,i)=>field('Level '+(i+1),`slots.${i}`,n,'number','min="0" max="20"')).join('')}</div><p class="sm">Enter capacity for your actual class / multiclass. Pact Magic or other short-rest pools can use resource trackers.</p></div>
${['attacks','spells','items','features','resources','forms'].map(k=>`<section><div class="section-head"><h2>${k.toUpperCase()}</h2>${button('+ ADD','add',`data-kind="${k}"`)}</div>${c[k].map((e,i)=>editor(k,e,i)).join('')||empty('Nothing added yet.')}</section>`).join('')}`;}
function editor(k,e,i){const p=`${k}.${i}.`,f=(label,key,type='text',extra='')=>field(label,p+key,e[key],type,extra),a=(label,key)=>area(label,p+key,e[key]),s=(label,key,opts)=>select(label,p+key,e[key],opts);let html=f('Name','name');
if(k==='attacks')html+=s('Ability','ability',ABILITIES)+f('Use spell attack bonus','spellAttack','checkbox')+f('Proficient','proficient','checkbox')+f('Attack bonus','bonus','number')+f('Damage / healing formula','damage')+f('Damage type','damageType')+f('Range / reach','range')+f('Healing (never critical)','heal','checkbox');
if(k==='spells')html+=f('Level (0 = cantrip)','level','number','min="0" max="9"')+f('Prepared','prepared','checkbox')+f('Always prepared','always','checkbox')+f('Casting time','castingTime')+f('Range','range')+f('Duration','duration')+f('Components / costs','components')+f('Concentration','concentration','checkbox')+f('Ritual','ritual','checkbox')+s('Roll type','rollKind',[['none','Utility / effect'],['attack','Spell attack + damage'],['damage','Damage / save'],['heal','Healing']])+f('Effect dice','roll')+f('Target save (e.g. DEX)','save')+f('Damage type','damageType');
if(k==='items')html+=f('Quantity','quantity','number','min="0"')+f('Weight each (lb.)','weight','number','min="0"')+f('Equipped / held','equipped','checkbox')+f('Requires attunement','requiresAttunement','checkbox')+f('Attuned','attuned','checkbox')+f('AC bonus','ac','number')+f('All saves bonus','saves','number')+f('Spell attack bonus','spellAttack','number')+f('Spell DC bonus','spellDc','number')+f('Optional dice','roll');
if(k==='features')html+=f('Optional dice','roll');
if(k==='resources')html+=f('Maximum','max','number','min="0" max="999"')+f('Used / damage','used','number','min="0"')+s('Reset fully on','reset',[['long','Long rest'],['short','Short / long rest'],['none','Manual only']])+f('Restore amount on short rest','shortAmount','number','min="0"');
if(k==='forms')html+=['str','dex','con','ac','speed','tempHp'].map(key=>f(key.toUpperCase(),key,'number')).join('')+f('Resource name to spend','resource')+`<label class="fullwidth">Attacks — one per line: Name | bonus | dice<textarea data-form-attacks="${i}">${esc(e.attacks.map(a=>`${a.name} | ${a.bonus} | ${a.damage}`).join('\n'))}</textarea></label>`;
html+=a('Description / play notes','description');return `<details class="editor" data-editor="${k}.${i}"><summary>${esc(e.name||'Unnamed '+k)}</summary><div class="builder-grid">${html}</div><div class="roll-row">${button('REMOVE','remove',`data-kind="${k}" data-index="${i}"`,'b danger')}</div>${['attacks','spells','features','items'].includes(k)?'<p class="sm">Dice placeholders: @mod (attack ability), @spell (spellcasting modifier), @prof, @level. Examples: 1d8+@mod, 2d8+@spell. These are evaluated when rolling.</p>':''}</details>`;}
function setPath(obj,path,value){const parts=path.split('.');let target=obj;for(const part of parts.slice(0,-1))target=target[part];target[parts.at(-1)]=value;}
function refresh(){const open=[...document.querySelectorAll('details[open][data-editor]')].map(e=>e.dataset.editor);const scroll=window.scrollY;render();open.forEach(k=>{const e=document.querySelector(`[data-editor="${k}"]`);if(e)e.open=true;});window.scrollTo(0,scroll);}
function normalizeCurrent(){const c=current();const clean=validate(c);store.characters[store.characters.indexOf(c)]=clean;}
function record(label,expression,options={}){const c=current();const result=rollDice(expression,{mode:options.mode||mode,crit:!!(options.damage&&critical)});const item={...result,label:String(label).slice(0,300),character:c.name.slice(0,300),detail:result.groups.map(g=>g.text).join(' '),time:Date.now()};lastRoll=item;store.history.unshift(item);store.history=store.history.slice(0,60);persist();if(shared&&context)shareRoll({label:item.label,character:item.character,expression:item.expression,total:item.total,detail:item.detail,mode:item.mode,crit:item.crit}).catch(()=>notify('Roll saved locally, but sharing failed.'));notify(`${item.label}: ${item.total} · ${item.detail}`);return item;}
function modal(title,content,actions){const d=$('#dialog');d.innerHTML=`<h2 class="am">${esc(title)}</h2><div style="margin:12px 0">${content}</div><div class="roll-row">${actions}${button('CANCEL','close-dialog')}</div>`;d.showModal();}
function confirm(title,message,fn){modal(title,`<p>${esc(message)}</p>`,button('CONFIRM','confirm'));confirm.callback=fn;}
function download(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function addCharacter(c){rosterVisible=false;location.hash='sheet';if(store.characters.length>=50)throw Error('Character limit reached (50). Export and remove an unused character first.');store.characters.push(c);store.active=c.id;persist();render();}
$('#app').addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#spell-list').innerHTML=spellList(current(),stats(current()));return;}if(e.target.matches('textarea[data-path]')){setPath(current(),e.target.dataset.path,e.target.value);persist();}});
$('#app').addEventListener('change',e=>{try{const el=e.target,c=current();if(el.id==='comp-kind'){compendiumKind=el.value;compendiumSource='';render();return;}if(el.id==='comp-query'){compendiumQuery=el.value;render();return;}if(el.id==='comp-source'){compendiumSource=el.value;render();return;}if(el.id==='portrait-upload'){const file=el.files?.[0];if(!file)return;if(file.size>4*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Portrait must be a PNG, JPEG or WebP under 4 MB.');const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const g=canvas.getContext('2d');const side=Math.min(img.width,img.height);g.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,256,256);const data=canvas.toDataURL('image/webp',0.8);URL.revokeObjectURL(url);if(c){c.portrait=data;persist();render();notify('Portrait saved and resized.')}else if(wizard){wizard.portrait=data;const field=document.querySelector('[data-wizard="portrait"]');if(field)field.value=data;}};img.onerror=()=>{URL.revokeObjectURL(url);notify('Unable to read portrait image.')};img.src=url;return;}if(el.id==='contract-file'){const file=el.files?.[0];if(file){if(file.size>2000000)throw Error('Maximum file size is 2 MB.');file.text().then(content=>{$('#contract-json').value=content;}).catch(e=>notify(e.message))}return;}if(el.id==='character'){store.active=el.value;search='';persist();render();return;}if(el.id==='shared'){shared=el.checked;return;}if(el.dataset.path){let v=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;const path=el.dataset.path;if(path==='hitDie'||path.startsWith('skills.'))v=Number(v);setPath(c,path,v);normalizeCurrent();persist();refresh();}else if(el.dataset.saveProf){c.saves=ABILITIES.filter(a=>a===el.dataset.saveProf?el.checked:c.saves.includes(a));persist();refresh();}else if(el.dataset.formAttacks!==undefined){const rows=el.value.split('\n').filter(x=>x.trim());const attacks=rows.map(line=>{const fields=line.split('|').map(x=>x.trim());if(fields.length!==3||!Number.isFinite(Number(fields[1])))throw Error('Form attacks use: Name | bonus | dice');rollDice(fields[2]);return {name:fields[0],bonus:Number(fields[1]),damage:fields[2]};});c.forms[+el.dataset.formAttacks].attacks=attacks;persist();}}catch(err){notify(err.message);}});
async function action(el){const c=current(),s=c?stats(c):null,a=el.dataset.action,i=Number(el.dataset.index),v=el.dataset.value;

 switch(a){
 case'level-wizard':beginWizard('level');return;
 case'wizard-load':captureWizard();await fetchCategory(v);return;
 case'wizard-next':captureWizard();if(wizard.mode==='create'&&wizard.step===0&&!wizard.name.trim())throw Error('Enter a character name.');if((wizard.mode==='create'&&wizard.step===1)||(wizard.mode==='level'&&wizard.step===0)){if(!wizardClass().name)throw Error('Choose or enter a class.');wizard.hpGain='';if(wizard.mode==='create'){const data=wizardClass().data;if(Array.isArray(data?.proficiency))wizard.saves=data.proficiency.filter(a=>ABILITIES.includes(a));if(ABILITIES.includes(data?.spellcastingAbility))wizard.spellAbility=data.spellcastingAbility;}}wizard.step++;showWizard();return;
 case'wizard-back':captureWizard();wizard.step--;showWizard();return;
 case'wizard-finish':finishWizard();return;
 case'load-compendium':sourceBase=$('#data-base').value.trim();localStorage.setItem('dnd-chars-sheet:data-source',sourceBase);await fetchCategory(compendiumKind);return;
 case'brew-import':if(wizard)captureWizard();modal('Import homebrew compendium','<p>Choose a 5etools-compatible JSON file (maximum 3 MB). Supports classes, subclasses, class features, species, backgrounds, feats, spells and items. Saved locally in this browser.</p><input type="file" id="brew-file" accept=".json,application/json"><textarea id="brew-json" aria-label="Homebrew JSON" placeholder="Or paste JSON"></textarea>',button('IMPORT COMPENDIUM','brew-confirm'));return;
 case'brew-confirm':{const value=$('#brew-json').value;if(value.length>3000000)throw Error('File exceeds 3 MB.');await importBrew(JSON.parse(value));if(wizard)showWizard();else{$('#dialog').close();render();}return;}
 case'comp-add':{const e=compendium[i];if(e.kind==='class'){beginWizard('level',i);return;}addCompendiumEntry(c,e);persist();notify(e.name+' added.');return;}
 case'class-hit-die':{c.classes=classRows(c);const row=c.classes[i];if(!row||row.spent>=row.level)throw Error('No Hit Dice remaining for this class.');const r=record(row.name+' Hit Die','1d'+row.hitDie+sign(s.mods.con),{mode:'normal'});row.spent++;syncClasses(c);changeHp(c,Math.max(0,r.total));persist();refresh();return;}

 case'tab':if(v==='Compendium'){location.hash='compendium';render();return;}tab=v;search='';render();return;
 case'workspace':location.hash=v==='compendium'?'compendium':'sheet';render();return;
 case'mode':mode=v;refresh();return;
 case'crit':critical=!critical;refresh();return;
 case'settings':settingsVisible=true;render();return;
 case'close-settings':settingsVisible=false;render();return;
 case'contract-export':{const {exportText}=await import(new URL('../content-contract.js',location.href).href);const data=JSON.parse(exportText('characters',store.characters.map(c=>({id:c.id,name:c.name,type:'character',data:c}))));download(data,'shattered-crucible-characters-v1.json');return;}
 case'contract-import':modal('Import Contract v1 characters','<p>Choose a Shattered Crucible Contract v1 JSON file (character entries).</p><input id="contract-file" type="file" accept=".json,application/json"><textarea id="contract-json" placeholder="Or paste Contract v1 JSON"></textarea>',button('IMPORT VALIDATED','contract-confirm'));return;
 case'contract-confirm':{const {importExchange}=await import(new URL('../content-contract.js',location.href).href);const raw=JSON.parse($('#contract-json').value);const incoming=importExchange('characters',raw);if(!window.confirm('Import '+incoming.length+' characters as new sheets? Existing characters stay intact.'))return;for(const item of incoming){const raw=item.data||item;const c=validate({...raw,schema:1});c.id=uid();store.characters.push(c)}persist();settingsVisible=false;rosterVisible=true;$('#dialog').close();render();return;}
 case'roster':rosterVisible=true;location.hash='roster';render();return;
 case'open-sheet':store.active=v;rosterVisible=false;location.hash='sheet';persist();render();return;
 case'new':beginWizard();return;
 case'preset':addCharacter(vox());return;
 case'duplicate':{const n=validate(c);n.id=uid();n.name+=' (copy)';addCharacter(n);return;}
 case'delete-character':confirm('Delete character?',`Delete ${c.name} from this browser? Token snapshots are unaffected. Export first if you need a backup.`,()=>{store.characters=store.characters.filter(x=>x.id!==c.id);store.active=store.characters[0]?.id;persist();render();});return;
 case'add':c[el.dataset.kind].push(entry(el.dataset.kind));persist();refresh();document.querySelector(`[data-editor="${el.dataset.kind}.${c[el.dataset.kind].length-1}"]`)?.setAttribute('open','');return;
 case'remove':confirm('Remove entry?',`Remove ${c[el.dataset.kind][i].name}?`,()=>{if(el.dataset.kind==='forms')c.activeForm=null;c[el.dataset.kind].splice(i,1);persist();refresh();});return;
 case'damage':case'heal':{const amount=clamp($('#hpAmount').value,0,9999);changeHp(c,a==='damage'?-amount:amount);break;}
 case'temp':c.tempHp=Math.max(c.tempHp,clamp($('#hpAmount').value,0,9999));break;
 case'roll':record(el.dataset.label||el.textContent,el.dataset.expression,{damage:el.dataset.damage==='true'});if(tab==='Dice')refresh();return;
 case'formula':record('Custom roll',$('#formula').value,{damage:$('#formulaDamage').checked});refresh();return;
 case'resource':c.resources[i].used=clamp(c.resources[i].used+Number(v),0,c.resources[i].max);break;
 case'rest':confirm(v==='long'?'Finish long rest?':'Finish short rest?',v==='long'?'Restore HP, slots, configured rest resources and Hit Dice (edition-dependent), clear temporary HP, concentration and active form?':'Restore short-rest resources. Spend Hit Dice separately to heal.',()=>{rest(c,v);persist();refresh();notify(v+' rest complete.');});return;
 case'hit-die':if(c.hitDiceSpent>=c.level)throw Error('No Hit Dice remaining.');{const r=record('Hit Die','1d'+c.hitDie+sign(s.mods.con),{mode:'normal'});c.hitDiceSpent++;changeHp(c,Math.max(0,r.total));break;}
 case'death':if(c.hp>0)throw Error('Death saves are tracked at 0 HP.');if(c.deathFail>=3||c.deathSuccess>=3)throw Error('Death save tracking is complete. Reset to start again.');{const r=record('Death save','1d20',{mode:'normal'});if(r.natural===20)changeHp(c,1);else if(r.natural===1)c.deathFail=Math.min(3,c.deathFail+2);else if(r.total>=10)c.deathSuccess=Math.min(3,c.deathSuccess+1);else c.deathFail=Math.min(3,c.deathFail+1);break;}
 case'death-reset':c.deathSuccess=c.deathFail=0;break;
 case'condition':c.conditions=c.conditions.includes(v)?c.conditions.filter(x=>x!==v):[...c.conditions,v];break;
 case'slot':c.spentSlots[i]=Number(v)<c.spentSlots[i]?Number(v):Number(v)+1;break;
 case'cast':case'ritual':{const sp=c.spells[i];if(c.activeForm!==null)throw Error('Revert from your form before casting, or track an allowed exception manually.');if(sp.level&&!sp.prepared&&!sp.always)throw Error('Prepare this spell in Builder first.');if(a==='cast'&&sp.level){const level=Number($('#cast-level-'+i).value);if(c.spentSlots[level-1]>=c.slots[level-1])throw Error('No available slot at that level.');c.spentSlots[level-1]++;}if(sp.concentration)c.concentration=sp.name;notify(`${sp.name}: ${a==='ritual'?'ritual tracked':'cast tracked'}. Roll its effect separately.`);break;}
 case'form':{const f=c.forms[i],r=f.resource?c.resources.find(r=>r.name.toLowerCase()===f.resource.toLowerCase()):null;if(f.resource&&!r)throw Error('Add a resource named '+f.resource+' or clear the form’s resource field.');if(r&&r.used>=r.max)throw Error('No '+r.name+' uses remaining.');if(r)r.used++;c.activeForm=i;c.tempHp=Math.max(c.tempHp,f.tempHp);break;}
 case'revert':c.activeForm=null;break;
 case'clear-history':store.history=[];lastRoll=null;break;
 case'export':modal('Export character','<p>Includes this character, notes, spells and inventory. Keep JSON backups before clearing browser data.</p><textarea id="json-data" aria-label="Character JSON" readonly>'+esc(JSON.stringify(c,null,2))+'</textarea>',button('DOWNLOAD JSON','download'));return;
 case'download':download(c,c.name.replace(/[^a-z0-9_-]/gi,'_')+'.json');return;
 case'import':modal('Import character','<p>Import a dnd-chars-sheet JSON export as a new character. Your current character stays intact.</p><input id="import-file" type="file" accept=".json,application/json"><textarea id="json-data" placeholder="Or paste character JSON here" aria-label="Character JSON"></textarea>',button('IMPORT AS NEW','import-confirm'));return;
 case'import-confirm':{const value=$('#json-data').value;if(value.length>500000)throw Error('JSON is too large (maximum 500 KB).');const n=validate(JSON.parse(value));n.id=uid();addCharacter(n);$('#dialog').close();notify('Character imported.');return;}
 case'save-token':{const token=await inspectToken();confirm('Save shared token snapshot?',`Save ${c.name} to ${token.name}? This shares the entire sheet, including all notes, with room participants who can access the token.${token.hasSheet?' The existing token snapshot will be replaced.':''} Local edits will not auto-update it.`,async()=>{await saveToken(c,token.id);notify('Token snapshot saved.');});return;}
 case'load-token':{const n=await loadToken();n.id=uid();addCharacter(n);notify('Token snapshot loaded as a new local character.');return;}
 case'print':{const before=tab;const main=$('main');main.innerHTML=tabs.filter(t=>!['Builder','Dice','Compendium'].includes(t)).map(t=>{tab=t;return `<section><h2>${esc(t)}</h2>${panel(c,s)}</section>`;}).join('');main.querySelectorAll('details').forEach(d=>d.open=true);window.print();tab=before;render();return;}
 case'close-dialog':wizard=null;$('#dialog').close();return;
 case'confirm':{const fn=confirm.callback;confirm.callback=null;$('#dialog').close();await fn?.();return;}
 }
 persist();refresh();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el).catch(err=>notify(err.message||'Action failed.'));});
$('#dialog').addEventListener('change',async e=>{if(e.target.id==='brew-file'){try{const file=e.target.files?.[0];if(!file)return;if(file.size>3000000)throw Error('File exceeds 3 MB.');$('#brew-json').value=await file.text();}catch(err){notify(err.message);}return;}if(e.target.id!=='import-file')return;try{const file=e.target.files?.[0];if(!file)return;if(file.size>500000)throw Error('JSON is too large (maximum 500 KB).');$('#json-data').value=await file.text();}catch(err){notify(err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='formula'){e.preventDefault();action(document.querySelector('[data-action="formula"]')).catch(err=>notify(err.message));}});
async function boot(){try{context=await connect();if(context)scope=`dnd-chars-sheet:${context.room}:${context.player}:v1`;init();fetchCategory('class');if(context)receiveRoll(data=>{store.history.unshift({...data,remote:true,time:Date.now()});store.history=store.history.slice(0,60);persist();if(tab==='Dice'&&$('#history'))$('#history').innerHTML=history();});}catch(err){$('#app').innerHTML=`<p class="note">Could not connect to Owlbear Rodeo: ${esc(err.message)}. Reopen the extension to retry.</p>`;}}

let compendium=[],compendiumStatus='Loading default 5etools classes…',compendiumKind='class',compendiumQuery='',compendiumSource='',compendiumBusy=false;
let sourceBase=DEFAULT_SOURCE,wizard=null;
try{sourceBase=localStorage.getItem('dnd-chars-sheet:data-source')||DEFAULT_SOURCE;const saved=JSON.parse(localStorage.getItem('dnd-chars-sheet:homebrew')||'[]');if(Array.isArray(saved))for(const raw of saved.slice(0,20))compendium=mergeCompendium(compendium,parseCompendium(raw));}catch{}
const optionsHtml=(list,value='')=>list.map(([v,label])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const catalogOptions=kind=>compendium.map((e,i)=>[e,i]).filter(([e])=>e.kind===kind).sort((a,b)=>a[0].name.localeCompare(b[0].name)).map(([e,i])=>[i,e.name+' · '+e.source]);
function appNavigation(){const catalog=location.hash==='#compendium';return `<div class="app-navigation no-print"><a class="app-wordmark" href="#sheet"><span class="brand-mark">◈</span> DND <span>CHARACTER SHEETS</span></a><div class="workspace-switch">${button('Character sheet','workspace','data-value="sheet" aria-current="'+(!catalog?'page':'false')+'"',!catalog?'b active':'b')}${button('Compendium','workspace','data-value="compendium" aria-current="'+(catalog?'page':'false')+'"',catalog?'b active':'b')}</div></div>`;}
function emptySheet(){return `<main class="empty-sheet"><div class="empty-emblem" aria-hidden="true">◈</div><p class="eyebrow">THE ADVENTURE IS YOURS</p><h1>A new story awaits.</h1><p class="empty-description">Bring your next character to life. Our guided builder takes you from a name and an idea to a sheet ready for the table.</p><div class="empty-actions">${button('Create a character →','new','','b primary')}${button('Import a sheet','import')}</div><button class="text-button" data-action="load-token" ${context?'':'disabled'}>Load an existing token snapshot</button><div class="empty-steps"><span><b>01</b> Choose your origins</span><span><b>02</b> Build your abilities</span><span><b>03</b> Start your adventure</span></div></main>`;}
function compendiumPage(){return `<main class="compendium-workspace"><div class="page-heading"><div><p class="eyebrow">YOUR REFERENCE LIBRARY</p><h1>Compendium</h1><p>Explore classes, spells, equipment and your own homebrew.</p></div><div class="catalog-destination">${current()?`<label>Add content to<select id="character" aria-label="Target character">${store.characters.map(c=>`<option value="${esc(c.id)}" ${c.id===current().id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:'<p>Create a character to add entries to a sheet.</p>'}</div></div>${compendiumPanel()}</main>`;}
function classPanel(c){const rows=classRows(c);return `<section class="c"><h2>Class progression · level ${c.level}</h2>${rows.map((r,i)=>`<div class="tr"><div><b>${esc(r.name)} ${r.level}</b><small>${esc(r.source)} · ${esc(r.subclass||'No subclass')} · ${r.level-r.spent}/${r.level} d${r.hitDie}</small>${c.classes?.length?field('Subclass',`classes.${i}.subclass`,r.subclass):''}</div>${button('SPEND HIT DIE','class-hit-die',`data-index="${i}" ${r.spent>=r.level?'disabled':''}`)}</div>`).join('')||'<p>Choose your first class using the wizard.</p>'}<div class="toolbar">${button(rows.length?'LEVEL UP / MULTICLASS':'CHOOSE CLASS','level-wizard',c.level>=20&&rows.length?'disabled':'')}${button('BROWSE COMPENDIUM','tab','data-value="Compendium"')}</div><p class="sm">Each class keeps its own level and Hit Dice. Review prerequisites, subclass choices, feats and spell slots when leveling.</p></section><br>`;}
function compendiumPanel(){const matches=compendium.map((e,i)=>[e,i]).filter(([e])=>e.kind===compendiumKind&&(!compendiumSource||e.source===compendiumSource)&&e.name.toLowerCase().includes(compendiumQuery.toLowerCase()));return `<section class="c catalog-panel"><details class="source-settings"><summary>Data sources & settings</summary><p class="sm">Default: 5etools data mirror. Classes and class features load automatically; load other categories as needed. Spells load PHB and XPHB; import additional books or homebrew as JSON.</p><label>HTTPS data directory<input id="data-base" value="${esc(sourceBase)}"></label></details><div class="toolbar catalog-toolbar"><select id="comp-kind" aria-label="Compendium category">${optionsHtml([['class','Classes'],['subclass','Subclasses'],['classFeature','Class features'],['subclassFeature','Subclass features'],['race','Species / races'],['background','Backgrounds'],['feat','Feats'],['spell','Spells'],['item','Items']],compendiumKind)}</select>${button(compendiumBusy?'LOADING…':'LOAD CATEGORY','load-compendium',compendiumBusy?'disabled':'')}${button('IMPORT HOMEBREW JSON','brew-import')}</div><p role="status" class="sm">${esc(compendiumStatus)}</p><div class="builder-grid"><label>Search<input id="comp-query" value="${esc(compendiumQuery)}"></label><label>Source<select id="comp-source">${optionsHtml([['','All sources'],...[...new Set(compendium.filter(e=>e.kind===compendiumKind).map(e=>e.source))].sort().map(s=>[s,s])],compendiumSource)}</select></label></div><p class="catalog-count">${matches.length} entries · Showing up to 60 matches</p><div class="catalog-grid">${matches.slice(0,60).map(([e,i])=>`<details class="editor catalog-card"><summary><span>${esc(e.name)}</span><small class="source-badge">${esc(e.source)}</small></summary><p class="comp-description">${esc(plain(e.data.entries)||'Choose this class in the character or level-up wizard.')}</p>${current()?button(e.kind==='class'?'USE IN LEVEL WIZARD':'ADD TO SHEET','comp-add',`data-index="${i}"`):button('CREATE CHARACTER','new')}</details>`).join('')||'<p class="list-empty">No matching entries. Load this category or adjust your search.</p>'}</div></section>`;}
async function fetchCategory(kind='class'){if(compendiumBusy)return;compendiumBusy=true;compendiumStatus='Loading '+kind+' from 5etools…';refreshCompendium();try{const added=await loadCompendium(['subclass','classFeature','subclassFeature'].includes(kind)?'class':kind,sourceBase);compendium=mergeCompendium(compendium,added);compendiumStatus='Loaded '+added.length+' entries. '+compendium.length+' available in this session.';}catch(e){compendiumStatus='Could not load data: '+e.message+'. Retry, change the HTTPS data directory, or import JSON. Existing sheets still work.';}finally{compendiumBusy=false;refreshCompendium();}}
function refreshCompendium(){if(store&&location.hash==='#compendium')render();if(wizard&&$('#dialog').open&&!$('#brew-json')){captureWizard();showWizard();}}
function beginWizard(mode='create',catalogIndex){const c=current();wizard={mode,step:0,entityType:'PC',portrait:'',tokenFrame:'gold',cr:'',owner:'',creatureType:'',size:'Medium',name:mode==='create'?'':c?.name||'',species:'',background:'',rules:mode==='create'?'2024':c.rules,classChoice:catalogIndex!==undefined?'catalog:'+catalogIndex:mode==='level'&&classRows(c).length?'existing:0':'custom',className:'',subclass:'',hitDie:8,hpGain:'',skills:[],saves:[],spellChoices:[],itemChoices:[],featChoices:[],spellAbility:'wis',slots:'0,0,0,0,0,0,0,0,0',abilities:{str:10,dex:10,con:10,int:10,wis:10,cha:10},speciesChoice:'',backgroundChoice:''};showWizard();}
function wizardClass(){const w=wizard;if(w.classChoice.startsWith('existing:')){const r=classRows(current())[Number(w.classChoice.split(':')[1])];if(r)return {...r,existing:true};}if(w.classChoice.startsWith('catalog:')){const e=compendium[Number(w.classChoice.split(':')[1])];if(e?.kind==='class')return {name:e.name,source:e.source,hitDie:e.data.hd?.faces||8,data:e.data};}return {name:w.className.trim(),source:'Custom',hitDie:Number(w.hitDie)};}
function captureWizard(){for(const el of document.querySelectorAll('[data-wizard]')){const key=el.dataset.wizard;if(key.startsWith('ability:'))wizard.abilities[key.split(':')[1]]=Number(el.value);else wizard[key]=el.multiple?[...el.selectedOptions].map(o=>o.value):el.value;}}
function wizardMulti(label,key,values,list){return `<label>${esc(label)}<select multiple size="6" data-wizard="${key}">${list.map(([v,label])=>`<option value="${esc(v)}" ${values.map(String).includes(String(v))?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;}
function wizardInput(label,key,value,type='text',extra=''){return `<label>${esc(label)}<input data-wizard="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function wizardSelect(label,key,value,list){return `<label>${esc(label)}<select data-wizard="${key}">${optionsHtml(list,value)}</select></label>`;}
function showWizard(){const w=wizard;if(!w)return;const creation=w.mode==='create',steps=creation?['Identity & origins','Class','Abilities','Training & magic','Equipment & feats','Review']:['Class','Hit points & review'];const step=w.step;let body=`<div class="wizard-progress" aria-label="Step ${step+1} of ${steps.length}">${steps.map((label,i)=>`<span class="${i===step?'current':i<step?'complete':''}"><b>${i+1}</b><small>${label}</small></span>`).join('')}</div><h3>${steps[step]}</h3><div class="builder-grid">`;
if(creation&&step===0)body+=wizardSelect('Sheet type','entityType',w.entityType,[['PC','Player Character'],['NPC','NPC'],['Familiar','Familiar / Pet'],['Monster','Monster']])+wizardInput('Portrait URL (HTTPS)','portrait',w.portrait)+wizardSelect('Token frame','tokenFrame',w.tokenFrame,['gold','silver','arcane','nature','infernal','none'].map(x=>[x,x.toUpperCase()]))+wizardInput('Owner / handler','owner',w.owner)+wizardInput('Challenge rating','cr',w.cr)+wizardInput('Creature type','creatureType',w.creatureType)+wizardSelect('Size','size',w.size,['Tiny','Small','Medium','Large','Huge','Gargantuan'].map(x=>[x,x]))+wizardInput('Character name','name',w.name)+wizardSelect('Rules','rules',w.rules,[['2024','2024'],['2014','2014'],['Custom','Custom']])+wizardSelect('Species from compendium','speciesChoice',w.speciesChoice,[['','Custom / choose later'],...catalogOptions('race')])+wizardInput('Custom species / ancestry','species',w.species)+wizardSelect('Background from compendium','backgroundChoice',w.backgroundChoice,[['','Custom / choose later'],...catalogOptions('background')])+wizardInput('Custom background','background',w.background)+`<div class="fullwidth toolbar">${button('LOAD SPECIES','wizard-load','data-value="race"')}${button('LOAD BACKGROUNDS','wizard-load','data-value="background"')}${button('IMPORT HOMEBREW','brew-import')}</div>`;
if((creation&&step===1)||(!creation&&step===0)){const existing=creation?[]:classRows(current()).map((r,i)=>['existing:'+i,r.name+' '+r.level+' → '+(r.level+1)+' · '+r.source]);body+=wizardSelect('Advance a class or choose a new class','classChoice',w.classChoice,[...existing,['custom','Custom / homebrew class'],...catalogOptions('class').filter(([,label])=>!w.rules||w.rules==='Custom'||!label.endsWith(w.rules==='2024'?' · PHB':' · XPHB')).map(([i,label])=>['catalog:'+i,label])])+wizardInput('Custom class name','className',w.className)+wizardSelect('Custom Hit Die','hitDie',w.hitDie,[6,8,10,12].map(n=>[n,'d'+n]))+wizardInput('Subclass (optional)','subclass',w.subclass)+`<p class="sm fullwidth">Source labels distinguish editions. A new class adds one level. Multiclass ability prerequisites and starting proficiencies need your review. ${esc(compendiumStatus)}</p><div class="toolbar">${button('RELOAD CLASSES','wizard-load','data-value="class"')}${button('IMPORT HOMEBREW','brew-import')}</div>`;}
if(creation&&step===2)body+=ABILITIES.map(a=>wizardInput(a.toUpperCase(),'ability:'+a,w.abilities[a],'number','min="1" max="30"')).join('')+'<p class="sm fullwidth">Enter your final scores, including origin bonuses. Standard array: 15, 14, 13, 12, 10, 8. Rolls and point-buy choices are entered manually.</p>';

if(creation&&step===3)body+=wizardMulti('Skill proficiencies','skills',w.skills,Object.keys(SKILLS).map(k=>[k,k]))+wizardMulti('Saving throw proficiencies','saves',w.saves,ABILITIES.map(a=>[a,a.toUpperCase()]))+wizardSelect('Spellcasting ability','spellAbility',w.spellAbility,ABILITIES.map(a=>[a,a.toUpperCase()]))+wizardInput('Spell slots, levels 1–9 (comma separated)','slots',w.slots)+wizardMulti('Starting spells','spellChoices',w.spellChoices,catalogOptions('spell'))+`<p class="sm fullwidth">Choose proficiencies and spells allowed by your class and origin. Leave slots at zero for a noncaster. Hold Ctrl / Cmd to select multiple entries.</p><div class="toolbar">${button('LOAD SPELLS','wizard-load','data-value="spell"')}</div>`;
if(creation&&step===4)body+=wizardMulti('Starting equipment','itemChoices',w.itemChoices,catalogOptions('item'))+wizardMulti('Starting feats (if granted)','featChoices',w.featChoices,catalogOptions('feat'))+`<p class="sm fullwidth">Choose your starting items and origin feat as applicable. Item effects and attack formulas remain editable in Builder.</p><div class="toolbar">${button('LOAD EQUIPMENT','wizard-load','data-value="item"')}${button('LOAD FEATS','wizard-load','data-value="feat"')}</div>`;
if(step===steps.length-1){const cls=wizardClass(),c=creation?null:current(),total=creation?0:classRows(c).reduce((n,r)=>n+r.level,0),con=creation?Math.floor((w.abilities.con-10)/2):Math.floor((c.abilities.con-10)/2);const suggested=Math.max(1,(total===0?Number(cls.hitDie):Math.floor(Number(cls.hitDie)/2)+1)+con);if(w.hpGain==='')w.hpGain=suggested;body+=`<p class="fullwidth"><b>${esc(w.name)}</b> · ${esc(cls.name)} · ${esc(cls.source)} · total level ${total+1}<br>d${cls.hitDie}; suggested HP ${suggested} (includes CON).</p>`+wizardInput(total===0?'Starting maximum HP':'HP gained this level','hpGain',w.hpGain,'number','min="1" max="1000"')+'<p class="sm fullwidth">Class features for this level are added when available. Choose skill/save proficiencies, equipment, subclass features, feats, spells and spell slots in Builder or Compendium. Imported descriptions do not automatically apply every rule or choice.</p>';}
body+='</div>';modal(creation?'Create character':'Level up / multiclass',body,(step?button('BACK','wizard-back'):'')+button(step===steps.length-1?(creation?'CREATE CHARACTER':'APPLY LEVEL'):'NEXT',step===steps.length-1?'wizard-finish':'wizard-next'));
}
function finishWizard(){captureWizard();const w=wizard,cls=wizardClass();if(!cls.name)throw Error('Choose or enter a class.');if(w.mode==='create'&&!w.name.trim())throw Error('Enter a character name.');const c=w.mode==='create'?blank():current();if(w.mode==='create'&&Object.values(w.abilities).some(n=>!Number.isInteger(n)||n<1||n>30))throw Error('Ability scores must be whole numbers from 1 to 30.');if(w.mode==='create'){c.entityType=w.entityType||'PC';c.portrait=(w.portrait&&/^https:\/\//i.test(w.portrait))?w.portrait:'';c.tokenFrame=w.tokenFrame||'gold';c.cr=w.cr||'';c.owner=w.owner||'';c.creatureType=w.creatureType||'';c.size=w.size||'Medium';c.name=w.name.trim();c.rules=w.rules;c.abilities={...w.abilities};c.saves=w.saves;c.skills=Object.fromEntries(w.skills.map(k=>[k,1]));c.spellAbility=w.spellAbility;
 const capacities=w.slots.split(',').map(Number);if(capacities.length!==9||capacities.some(n=>!Number.isInteger(n)||n<0||n>20))throw Error('Enter nine slot capacities from 0 to 20.');
 c.slots=capacities;
 for(const key of ['spellChoices','itemChoices','featChoices'])for(const index of w[key])if(compendium[Number(index)])addCompendiumEntry(c,compendium[Number(index)]);
 c.spells.forEach(e=>e.prepared=true);
 c.species=w.species;c.background=w.background;for(const key of ['speciesChoice','backgroundChoice'])if(w[key]!==''&&compendium[Number(w[key])])addCompendiumEntry(c,compendium[Number(w[key])]);}
advance(c,{...cls,subclass:w.subclass,hpGain:Number(w.hpGain),features:compendium.filter(e=>e.kind==='classFeature')});
wizard=null;$('#dialog').close();tab=moduleMode==='builder'?'Builder':'Overview';if(w.mode==='create')addCharacter(c);else{persist();render();}notify(w.mode==='create'?'Character created. Your character is ready. You can fine-tune its details in Builder.':'Level added. Review new choices and spell slot capacity in Builder.');}
async function importBrew(raw){const added=parseCompendium(raw);const previous=JSON.parse(localStorage.getItem('dnd-chars-sheet:homebrew')||'[]');const next=[...previous,raw];if(JSON.stringify(next).length>3000000)throw Error('Saved homebrew exceeds 3 MB. Use smaller compendium files.');localStorage.setItem('dnd-chars-sheet:homebrew',JSON.stringify(next));compendium=mergeCompendium(compendium,added);compendiumStatus='Imported and saved '+added.length+' homebrew entries.';notify(compendiumStatus);}

window.addEventListener('storage',event=>{if(event.key!==scope||!event.newValue||!store)return;try{const next=JSON.parse(event.newValue);if(!Array.isArray(next.characters))return;store={characters:next.characters.map(validate),active:next.active,history:Array.isArray(next.history)?next.history:[]};if(!store.characters.some(c=>c.id===store.active))store.active=store.characters[0]?.id;render()}catch(error){console.warn('Unable to refresh shared character store',error)}});
window.addEventListener('hashchange',()=>{if(store)render();});
boot();
